def run(_context):
    cam = mb.get_cam()
    setup = cam.setups.item(0)
    total = 0.0
    for op in setup.allOperations:
        try:
            mt = cam.getMachiningTime(op, 500.0, 10000.0, 8.0)
            t = mt.machiningTime
            total += t
            print(op.name, round(t/60, 2), 'min')
        except Exception as e:
            print(op.name, 'ERR', e)
    print('TOTAL', round(total/60, 2), 'min')

